'use strict';
const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const escapeHTML = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = n => new Intl.NumberFormat('uz-UZ').format(n) + ' so‘m';
const date = value => new Intl.DateTimeFormat('uz-UZ', {dateStyle:'medium',timeStyle:'short'}).format(new Date(value));
const normalize = value => String(value).toLocaleLowerCase().replace(/[‘’ʻʼ`]/g,"'").replace(/\s+/g,' ').trim();
const load = (key, fallback) => { try { return JSON.parse(localStorage.getItem(key)) ?? fallback; } catch { return fallback; } };
function save(key, value) { try { localStorage.setItem(key, JSON.stringify(value)); } catch { toast('Brauzer xotirasi band. Ma’lumotlar bu oynada saqlanadi.'); } }
const main = $('main');
const heroHTML = $('.hero').outerHTML + $('.benefits').outerHTML;
const aboutHTML = $('#about').outerHTML;
main.id = 'page-content'; main.tabIndex = -1;
let books = [], reviews = [], cart = load('kitobzor-cart', {}), favorites = load('kitobzor-favorites', []);
if (!cart || typeof cart !== 'object' || Array.isArray(cart)) cart = {};
if (!Array.isArray(favorites)) favorites = [];
let orderReceipts = load('kitobzor-receipts', []);
if (!Array.isArray(orderReceipts)) orderReceipts = [];
let timer, filters = {}, adminTab = 'overview', adminData, routeSequence = 0, ready = false;
const statuses = {new:'Yangi',confirmed:'Tasdiqlangan',shipped:'Yetkazilmoqda',completed:'Yakunlangan',cancelled:'Bekor qilingan',pending:'Tekshirilmoqda',approved:'Tasdiqlangan',rejected:'Rad etilgan'};
const transitions = {new:['confirmed','cancelled'],confirmed:['shipped','cancelled'],shipped:['completed'],completed:[],cancelled:[]};
function toast(text) { $('#toast').textContent=text; $('#toast').classList.add('visible'); clearTimeout(timer); timer=setTimeout(()=>$('#toast').classList.remove('visible'),3500); }
async function api(path, {method='GET', data, headers={}}={}) {
    const response = await fetch('/api'+path, {method, credentials:'same-origin',headers:{...(data ? {'Content-Type':'application/json'} : {}),...headers}, ...(data ? {body:JSON.stringify(data)} : {}),signal:AbortSignal.timeout(12000)});
    let result; try { result=await response.json(); } catch { throw new Error('Server javobi o‘qilmadi. Sahifani yangilang.'); }
    if (!response.ok) { const error=new Error(result.error || 'So‘rov bajarilmadi'); error.status=response.status; throw error; }
    return result;
}
function showError(form, error) { const box=$('.form-error',form); if (box) { box.hidden=false; box.textContent=error.message || 'Serverga ulanib bo‘lmadi. Qayta urinib ko‘ring.'; box.focus(); } else toast(error.message || 'Serverga ulanib bo‘lmadi'); }
const errorBox = '<p class="form-error" role="alert" tabindex="-1" hidden></p>';
const cover = b => `<div class="cover" style="--cover:${/^#[0-9a-f]{6}$/i.test(b.color)?b.color:'#284c41'};--paper:${/^#[0-9a-f]{6}$/i.test(b.paper)?b.paper:'#fff0c7'}"><small>${escapeHTML(b.author.toUpperCase())}</small><strong>${escapeHTML(b.title)}</strong><span class="ornament">${escapeHTML(b.symbol)}</span><span class="edition">KITOBZOR · MUTOLAA TO‘PLAMI</span></div>`;
const heading = (title, subtitle='', eyebrow='KITOBZOR') => `<div class="page-heading"><div class="eyebrow">${eyebrow}</div><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div>`;
const empty = (text, link='#catalog', label='Kitoblarni ko‘rish') => `<div class="empty panel"><span class="empty-symbol">⌑</span><p>${text}</p><a class="primary" href="${link}">${label} ↗</a></div>`;
function rating(bookId) { const list=reviews.filter(r=>r.bookId===bookId); return list.length?`${(list.reduce((s,r)=>s+r.rating,0)/list.length).toFixed(1)} · ${list.length} sharh`:'Hali sharh yo‘q'; }
function card(b) { return `<article class="book-card"><div class="cover-wrap" style="background:${b.color}12"><a class="cover-button" href="#book/${b.id}" aria-label="${escapeHTML(b.title)} haqida">${cover(b)}</a>${b.tag?`<span class="tag">${escapeHTML(b.tag)}</span>`:''}<button class="favorite ${favorites.includes(b.id)?'saved':''}" data-favorite="${b.id}" aria-label="${escapeHTML(b.title)}: sevimlilar" aria-pressed="${favorites.includes(b.id)}">${favorites.includes(b.id)?'♥':'♡'}</button></div><div class="book-meta"><p class="author">${escapeHTML(b.author)}</p><a class="book-title" href="#book/${b.id}">${escapeHTML(b.title)}</a><p class="rating">☆ ${rating(b.id)}</p><div class="book-bottom"><span class="price">${money(b.price)}</span><button class="add" data-add="${b.id}" ${b.stock<1?'disabled':''} aria-label="${escapeHTML(b.title)}ni savatchaga qo‘shish">+</button></div><p class="stock ${b.stock<1?'sold-out':''}">${b.stock>0?`${b.stock} dona mavjud`:'Vaqtincha tugagan'}</p></div></article>`; }
function cartLines() { return books.filter(b=>cart[b.id]).map(b=>({...b,quantity:cart[b.id]})); }
function cleanCart() {
    for (const id of Object.keys(cart)) { const b=books.find(b=>b.id===Number(id)); if(!b || !Number.isInteger(cart[id]) || cart[id]<1 || b.stock<1) delete cart[id]; else cart[id]=Math.min(cart[id],b.stock,99); }
    save('kitobzor-cart',cart);
}
function renderCart() {
    const lines=cartLines(), count=lines.reduce((s,b)=>s+b.quantity,0);
    $('#cart-count').textContent=count; $('#dialog-count').textContent=count?`(${count})`:'';
    $('#cart-items').innerHTML=lines.length?lines.map(b=>`<div class="cart-row"><div class="cart-info"><a href="#book/${b.id}" data-close-cart>${escapeHTML(b.title)}</a><p>${money(b.price)}</p><button class="remove" data-remove="${b.id}">Olib tashlash</button></div><div class="quantity"><button data-change="${b.id}" data-delta="-1" aria-label="Sonini kamaytirish">−</button><span>${b.quantity}</span><button data-change="${b.id}" data-delta="1" ${b.quantity>=Math.min(b.stock,99)?'disabled':''} aria-label="Sonini oshirish">+</button></div><strong>${money(b.price*b.quantity)}</strong></div>`).join(''):'<div class="empty">Savatchangiz bo‘sh. Yangi hikoyaga joy ochamizmi?</div>';
    $('#cart-summary').innerHTML=lines.length?`<div class="total"><span>Kitoblar jami</span><strong>${money(lines.reduce((s,b)=>s+b.price*b.quantity,0))}</strong></div><a class="primary wide" data-close-cart href="#checkout">Buyurtmaga o‘tish ↗</a>`:'';
}
function updateCart() { save('kitobzor-cart',cart); renderCart(); if(location.hash.startsWith('#checkout')) renderCheckout(); }
function add(id) { const b=books.find(b=>b.id===id); if(!b) return; if((cart[id]||0)>=Math.min(b.stock,99)) return toast('Zaxirada bundan ko‘p kitob yo‘q.'); cart[id]=(cart[id]||0)+1; updateCart(); toast('Kitob savatchaga qo‘shildi'); }
async function refreshPublic() { const [b,r]=await Promise.all([api('/books'),api('/reviews')]); books=b.books; reviews=r.reviews; cleanCart(); renderCart(); }
function catalogShell(isSearch=false) {
    main.innerHTML=heading(isSearch?'Keyingi kitobingizni izlang.':'Qaysi hikoyadan boshlaymiz?', 'Muallif, nom, janr yoki byudjet — o‘zingizga mosini toping.',isSearch?'QIDIRUV':'KITOB JAVONI')+`<section class="catalog page-catalog"><form id="search-form" class="search-bar"><label for="search">Kitob yoki muallif</label><div class="search-row"><input id="search" name="q" type="search" placeholder="Masalan, O‘tkan kunlar yoki Qodiriy" value="${escapeHTML(filters.q||'')}"><button class="primary" type="submit">Qidirish ↗</button></div></form><div class="filter-row"><label>Janr<select id="category-filter"><option value="all">Barcha janrlar</option>${['Adabiyot','Rivojlanish','Bolalar'].map(c=>`<option ${filters.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label>Eng yuqori narx<input type="number" id="budget-filter" min="0" step="1000" placeholder="Cheklanmagan" value="${escapeHTML(filters.budget||'')}"></label><label>Saralash<select id="sort"><option value="popular">Tavsiya etilgan</option><option value="cheap">Avval arzonlari</option><option value="expensive">Avval qimmatlari</option><option value="name">Nomi bo‘yicha</option><option value="new">Yangi kelganlar</option></select></label><label class="check-label"><input id="stock-filter" type="checkbox" ${filters.available?'checked':''}> Faqat mavjudlari</label><button type="button" class="secondary" data-reset-filters>Tozalash</button></div><div id="result-count" class="result-line" role="status"></div><div id="books" class="book-grid"></div></section>`;
    $('#sort').value=filters.sort||'popular'; $('#category-filter').value=filters.category||'all'; renderResults(false);
}
function renderResults(sync=true) {
    if(!$('#books')) return;
    filters={q:$('#search').value,category:$('#category-filter').value,budget:$('#budget-filter').value,sort:$('#sort').value,available:$('#stock-filter').checked};
    const terms=normalize(filters.q).split(' ').filter(Boolean);
    let list=books.filter(b=>terms.every(t=>normalize(`${b.title} ${b.author} ${b.category}`).includes(t))&&(filters.category==='all'||b.category===filters.category)&&(!filters.budget||b.price<=Number(filters.budget))&&(!filters.available||b.stock>0));
    if(filters.sort==='cheap')list.sort((a,b)=>a.price-b.price);if(filters.sort==='expensive')list.sort((a,b)=>b.price-a.price);if(filters.sort==='name')list.sort((a,b)=>a.title.localeCompare(b.title,'uz'));if(filters.sort==='new')list.sort((a,b)=>b.id-a.id);
    $('#result-count').textContent=`${list.length} ta kitob topildi`; $('#books').innerHTML=list.length?list.map(card).join(''):'<div class="empty full-span">Mos kitob topilmadi. Narx chegarasini oshiring yoki filtrlarni tozalang.</div>';
    if(sync) { const params=new URLSearchParams(); for(const [k,v] of Object.entries(filters)) if(v&&v!=='all'&&v!=='popular')params.set(k,String(v)); history.replaceState(null,'',`#search${params.size?'?'+params:''}`); setActive('search'); }
}
function reviewForm(bookId) { return `<form id="review-form" class="panel form-stack"><h2>Fikringiz bilan bo‘lishing</h2><label>Kitob<select name="bookId" required>${books.map(b=>`<option value="${b.id}" ${Number(bookId)===b.id?'selected':''}>${escapeHTML(b.title)}</option>`).join('')}</select></label><div class="form-grid"><label>Ismingiz<input name="name" required minlength="2" maxlength="60" autocomplete="name"></label><label>Baho<select name="rating" required><option value="5">★★★★★ — 5</option><option value="4">★★★★☆ — 4</option><option value="3">★★★☆☆ — 3</option><option value="2">★★☆☆☆ — 2</option><option value="1">★☆☆☆☆ — 1</option></select></label></div><label>Sharhingiz<textarea name="text" required minlength="10" maxlength="2000" rows="4" placeholder="Kitob sizda qanday taassurot qoldirdi?"></textarea></label><small>Sharhingiz admin tasdig‘idan so‘ng hammaga ko‘rinadi. Shaxsiy telefon yoki manzil yozmang.</small>${errorBox}<button class="primary" type="submit">Sharh yuborish ↗</button><p class="form-success" role="status" hidden></p></form>`; }
function reviewCard(r) { const b=books.find(b=>b.id===r.bookId); return `<article class="review-card panel"><div class="review-top"><strong>${escapeHTML(r.name)}</strong><span class="stars" aria-label="${r.rating} ball">${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</span></div><a href="#book/${r.bookId}" class="muted">${escapeHTML(b?.title||'Arxivdagi kitob')}</a><p>${escapeHTML(r.text)}</p><time datetime="${r.createdAt}">${date(r.createdAt)}</time></article>`; }
function renderBook(id) {
    const b=books.find(b=>b.id===id); if(!b){main.innerHTML=heading('Kitob topilmadi')+empty('Bu kitob arxivlangan yoki mavjud emas.');return;}
    const list=reviews.filter(r=>r.bookId===id);
    main.innerHTML=`<a class="back-link" href="#catalog">← Kitoblar javoni</a><section class="book-page"><div class="detail-art">${cover(b)}</div><div class="detail-copy"><div class="eyebrow">${escapeHTML(b.category)}</div><h1>${escapeHTML(b.title)}</h1><p class="detail-author">${escapeHTML(b.author)}</p><a href="#book-reviews" data-scroll-reviews class="rating">☆ ${rating(id)}</a><p>${escapeHTML(b.description)}</p><div class="detail-price">${money(b.price)}</div><p class="stock">${b.stock?`${b.stock} dona zaxirada`:'Vaqtincha tugagan'}</p><div class="button-row"><button class="primary" data-add="${b.id}" ${b.stock<1?'disabled':''}>Savatchaga qo‘shish +</button><button class="secondary" data-favorite="${b.id}">${favorites.includes(id)?'♥ Saqlangan':'♡ Saqlash'}</button></div><small>Olib ketish — bepul · Lokal kuryer tarifi — 25 000 so‘m</small></div></section><section id="book-reviews" class="page-section"><h2>O‘quvchilar fikri</h2><div class="two-columns"><div>${list.length?list.map(reviewCard).join(''):'<div class="panel empty">Bu kitob haqida birinchi sharhni siz yozing.</div>'}</div>${reviewForm(id)}</div></section><section class="page-section"><h2>Yana yoqishi mumkin</h2><div class="book-grid">${books.filter(x=>x.id!==id&&x.category===b.category).slice(0,4).map(card).join('')}</div></section>`;
}
function renderReviews() { main.innerHTML=heading('Kitobdan qolgan taassurotlar.', 'O‘quvchilarning tasdiqlangan sharhlari.','O‘QUVCHILAR DAVRASI')+`<div class="two-columns page-section"><div><label class="standalone-label">Kitob bo‘yicha filtrlash<select id="review-filter"><option value="all">Barcha kitoblar</option>${books.map(b=>`<option value="${b.id}">${escapeHTML(b.title)}</option>`).join('')}</select></label><div id="review-list">${reviews.length?reviews.slice().reverse().map(reviewCard).join(''):'<div class="empty panel">Hozircha tasdiqlangan sharhlar yo‘q.</div>'}</div></div>${reviewForm()}</div>`; }
function renderAdviser() {
    main.innerHTML=heading('Sizga mos kitobni topamiz.', 'Bir necha tanlov qiling — javonimizdan didingiz va byudjetingizga mos asarlarni saralaymiz.','KITOB TAVSIYACHISI')+`<div class="adviser-layout"><form id="adviser-form" class="panel form-stack"><span class="adviser-star">✳</span><h2>Bugun nimani o‘qigingiz kelyapti?</h2><label>Kim uchun?<select name="reader"><option value="adult">O‘zim uchun / katta yoshdagilar</option><option value="child">Bola uchun</option></select></label><label>Qiziqish<select name="genre"><option value="all">Hammasiga ochiqman</option><option>Adabiyot</option><option>Rivojlanish</option><option>Bolalar</option></select></label><label>Kayfiyat va maqsad<select name="mood"><option value="any">Yangi bir hikoya</option><option value="inspire">O‘zimni rivojlantirish</option><option value="warm">Mehr va samimiyat</option><option value="adventure">Sarguzasht</option></select></label><label>Byudjet<select name="budget"><option value="10000000">Cheklanmagan</option><option value="40000">40 000 so‘mgacha</option><option value="50000">50 000 so‘mgacha</option><option value="70000">70 000 so‘mgacha</option></select></label><button class="primary" type="submit">Menga kitob tavsiya qiling ↗</button><small>Tavsiyalar siz tanlagan mezonlar asosida tuziladi.</small></form><div id="adviser-results" aria-live="polite"><div class="adviser-intro"><span>✦</span><h2>Har bir didning<br>o‘z hikoyasi bor.</h2><p>Tanlovlaringizni belgilang.<br>Natija shu yerda paydo bo‘ladi.</p></div></div></div>`;
}
function recommend(form) {
    const f=Object.fromEntries(new FormData(form));
    let list=books.filter(b=>b.stock>0&&b.price<=Number(f.budget)&&(f.reader!=='child'||b.category==='Bolalar')&&(f.genre==='all'||b.category===f.genre));
    const moodIds={inspire:[2,7],warm:[8,1,3],adventure:[6,4,3]};
    list=list.map(b=>({b,score:(moodIds[f.mood]?.includes(b.id)?5:0)+(f.mood==='inspire'&&b.category==='Rivojlanish'?3:0)})).sort((a,b)=>b.score-a.score||a.b.price-b.b.price).slice(0,3);
    $('#adviser-results').innerHTML=list.length?`<h2>Siz uchun ${list.length} ta tavsiya</h2><p class="muted">${f.reader==='child'?'Bolalar uchun · ':''}${f.genre==='all'?'Barcha janrlar':escapeHTML(f.genre)} · ${Number(f.budget)===10000000?'Byudjet cheklanmagan':money(Number(f.budget))+'gacha'}</p><div class="recommendations">${list.map(({b,score})=>`<div class="recommendation"><a href="#book/${b.id}">${cover(b)}</a><div><span class="eyebrow">${escapeHTML(b.category)}</span><h3><a href="#book/${b.id}">${escapeHTML(b.title)}</a></h3><p>${escapeHTML(b.description)}</p><p class="recommend-reason">${score>0?'Tanlangan kayfiyat va maqsadingizga yaqin.':'Tanlangan janr, yosh va byudjetga mos.'}</p><strong>${money(b.price)}</strong><button class="secondary" data-add="${b.id}">Savatchaga +</button></div></div>`).join('')}</div>`:empty('Bu tanlovlarga mos, zaxirada bor kitob topilmadi. Janrni almashtiring yoki byudjetni oshiring.','#adviser','Tanlovni yangilash');
}
function checkoutSummary() { const lines=cartLines(), subtotal=lines.reduce((s,b)=>s+b.price*b.quantity,0), shipping=$('[name="delivery"]')?.value==='courier'?25000:0; return `<h2>Buyurtma tarkibi</h2>${lines.map(b=>`<div class="summary-line"><span>${escapeHTML(b.title)} <small>× ${b.quantity}</small></span><strong>${money(b.price*b.quantity)}</strong></div>`).join('')}<div class="summary-line"><span>Kitoblar</span><span>${money(subtotal)}</span></div><div class="summary-line"><span>Yetkazish</span><span>${shipping?money(shipping):'Bepul'}</span></div><div class="total"><span>Jami</span><strong>${money(subtotal+shipping)}</strong></div><a class="text-link" href="#catalog">← Yana kitob qo‘shish</a>`; }
function renderCheckout() {
    if(!cartLines().length){main.innerHTML=heading('Buyurtma berish')+empty('Buyurtma berish uchun avval savatchaga kitob qo‘shing.');return;}
    main.innerHTML=heading('Yangi hikoyangizga bir qadam.', 'Ma’lumotlarni kiriting va buyurtmangizni tasdiqlang.','BUYURTMA VA TO‘LOV')+`<div class="checkout-layout"><form id="checkout-form" class="panel form-stack"><h2>1. Bog‘lanish ma’lumotlari</h2><div class="form-grid"><label>Ism va familiya<input name="name" required minlength="2" maxlength="100" autocomplete="name"></label><label>Telefon<input name="phone" type="tel" required maxlength="25" autocomplete="tel" placeholder="+998 90 123 45 67" pattern="[+0-9 ()\-]{9,25}"></label></div><h2>2. Yetkazish</h2><label>Qabul qilish usuli<select name="delivery" id="delivery"><option value="pickup">Olib ketish — bepul</option><option value="courier">Kuryer — 25 000 so‘m (namuna tarifi)</option></select></label><label id="address-label" hidden>Yetkazish manzili<textarea name="address" minlength="10" maxlength="300" rows="3" autocomplete="street-address" placeholder="Shahar, ko‘cha, uy va xonadon"></textarea></label><p id="pickup-note" class="inline-note">Olib ketish manzili va vaqti buyurtma tasdiqlanganda kelishiladi. Bu lokal namuna do‘kon.</p><h2>3. To‘lov usuli</h2><label>To‘lov<select name="payment" id="payment"><option value="cash">Qabul qilganda naqd — hali to‘lanmagan</option><option value="demo">Onlayn to‘lov — SINOV</option></select></label><p id="payment-note" class="inline-note">Buyurtma saqlanadi; to‘lov qabul qilish vaqtida amalga oshiriladi.</p><label class="check-label"><input name="consent" type="checkbox" required> Kiritilgan ma’lumotlar lokal serverda buyurtma uchun saqlanishiga roziman.</label>${errorBox}<button class="primary wide" type="submit">Buyurtmani tasdiqlash ↗</button><small>Onlayn sinovda haqiqiy pul yechilmaydi. Karta raqami yoki SMS kodi talab qilinmaydi.</small></form><aside class="panel order-summary" id="checkout-summary">${checkoutSummary()}</aside></div>`;
}
async function placeOrder(form) {
    const data=Object.fromEntries(new FormData(form));
    let requestId=sessionStorage.getItem('kitobzor-pending-order'); if(!requestId){requestId=crypto.randomUUID();sessionStorage.setItem('kitobzor-pending-order',requestId);}
    const result=await api('/orders',{method:'POST',data:{...data,requestId,items:cartLines().map(b=>({id:b.id,quantity:b.quantity}))}});
    orderReceipts=orderReceipts.filter(r=>r.id!==result.order.id);orderReceipts.unshift({id:result.order.id,token:result.receiptToken});save('kitobzor-receipts',orderReceipts);sessionStorage.removeItem('kitobzor-pending-order');cart={};updateCart();
    try { await refreshPublic(); } catch { /* The saved receipt remains available if a catalog refresh fails. */ }
    location.hash='#orders'; toast(`Buyurtma saqlandi: ${result.order.id}`);
}
function orderCard(o) { return `<article class="panel order-card"><div class="order-heading"><div><strong>${escapeHTML(o.id)}</strong><p class="muted">${date(o.createdAt)}</p></div><span class="badge ${o.status}">${statuses[o.status]||escapeHTML(o.status)}</span></div>${o.items.map(i=>`<div class="summary-line"><span>${escapeHTML(i.title)} × ${i.quantity}</span><strong>${money(i.price*i.quantity)}</strong></div>`).join('')}<div class="summary-line"><span>${o.delivery==='courier'?'Kuryer':'Olib ketish'}</span><span>${money(o.shipping)}</span></div><div class="total"><span>Jami</span><strong>${money(o.total)}</strong></div><p class="inline-note">${o.payment==='demo'?'Sinov to‘lovi: muvaffaqiyatli taqlid qilindi. Haqiqiy pul yechilmagan.':'Naqd to‘lov: hali to‘lanmagan.'}</p></article>`; }
async function renderOrders(sequence) {
    main.innerHTML=heading('Buyurtmalaringiz.', 'Shu brauzerdan berilgan buyurtmalar va ularning joriy holati.','MENING KITOBLARIM')+'<div id="order-list" class="page-section"><p role="status">Buyurtmalar yuklanmoqda…</p></div>';
    if(!orderReceipts.length){$('#order-list').innerHTML=empty('Hozircha buyurtma bermagansiz.');return;}
    const results=await Promise.allSettled(orderReceipts.map(r=>api('/orders/'+encodeURIComponent(r.id),{headers:{'X-Order-Token':r.token}})));
    if(sequence!==routeSequence)return;
    $('#order-list').innerHTML='<button class="secondary" data-refresh-orders>Holatni yangilash ↻</button>'+results.map((r,i)=>r.status==='fulfilled'?orderCard(r.value.order):`<div class="panel inline-note">${escapeHTML(orderReceipts[i].id)}: ${escapeHTML(r.reason.message)} <button class="secondary" data-forget-order="${escapeHTML(orderReceipts[i].id)}">Ro‘yxatdan olib tashlash</button></div>`).join('');
}
function renderAbout() { main.innerHTML=heading('Kitob bilan birga o‘samiz.','Kitobzor — yangi fikrlar va hikoyalar uchun kichik maskan.','BIZ HAQIMIZDA')+aboutHTML+`<div class="two-columns page-section"><section class="panel"><h2>Qanday ishlaydi?</h2><ol class="steps"><li>Kitobni qidiruv yoki tavsiyachi orqali tanlang.</li><li>Savatchaga qo‘shib, qabul qilish usulini belgilang.</li><li>Buyurtmani tasdiqlang va holatini kuzating.</li><li>Mutolaadan so‘ng taassurotingizni yozing.</li></ol></section><section class="panel faq"><h2>Ko‘p so‘raladigan savollar</h2><details><summary>Haqiqiy to‘lov ishlaydimi?</summary><p>Hozir onlayn to‘lov sinov rejimida. Pul yechilmaydi. Naqd to‘lov tanlovi ham buyurtma yozuvi sifatida saqlanadi.</p></details><details><summary>Yetkazish narxi qancha?</summary><p>Lokal namunada olib ketish bepul, kuryer uchun namuna tarifi 25 000 so‘m.</p></details><details><summary>Sharhim nega ko‘rinmayapti?</summary><p>Sharh admin tasdiqlagandan keyin ko‘rinadi.</p></details><details><summary>Ma’lumotlar qayerda saqlanadi?</summary><p>Kitoblar, sharhlar va buyurtmalar shu kompyuterdagi lokal serverda saqlanadi. Savatcha va sevimlilar shu brauzerda qoladi.</p></details></section></div>`; }
async function renderAdmin(sequence) {
    main.innerHTML=heading('Do‘kon boshqaruvi.', 'Kitoblar, zaxira, buyurtmalar va sharhlar — bir joyda.','ADMIN PANELI')+'<p role="status">Tekshirilmoqda…</p>';
    const session=await api('/admin/session'); if(sequence!==routeSequence)return;
    if(!session.authenticated){main.innerHTML=heading('Admin paneliga kirish.','Boshqaruv sahifasi parol bilan himoyalangan.','KITOBZOR BOSHQARUVI')+`<form id="login-form" class="panel form-stack login-form"><h2>Xush kelibsiz</h2><label>Login<input name="username" required value="admin" autocomplete="username"></label><label>Parol<input name="password" type="password" required autocomplete="current-password"></label>${errorBox}<button class="primary" type="submit">Kirish ↗</button><small>Kirish ma’lumotlari loyiha papkasidagi admin-access.txt faylida.</small></form>`;return;}
    adminData=await api('/admin/data');if(sequence!==routeSequence)return;renderAdminWorkspace();
}
function adminBookForm(b={}) { return `<form id="book-form" class="panel form-stack"><div class="section-line"><h2>${b.id?'Kitobni tahrirlash':'Yangi kitob'}</h2><button class="secondary" type="button" data-new-book>Tozalash</button></div><input type="hidden" name="id" value="${b.id||''}"><div class="form-grid"><label>Kitob nomi<input name="title" required minlength="2" maxlength="120" value="${escapeHTML(b.title||'')}"></label><label>Muallif<input name="author" required minlength="2" maxlength="100" value="${escapeHTML(b.author||'')}"></label><label>Janr<select name="category">${['Adabiyot','Rivojlanish','Bolalar'].map(c=>`<option ${b.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label>Narx (so‘m)<input name="price" type="number" min="1000" max="10000000" step="1" required value="${b.price||''}"></label><label>Zaxira (dona)<input name="stock" type="number" min="0" max="10000" step="1" required value="${b.stock??0}"></label><label>Muqova rangi<input name="color" type="color" value="${b.color||'#284c41'}"></label></div><label>Belgi / yorliq<input name="tag" maxlength="40" value="${escapeHTML(b.tag||'')}" placeholder="Masalan, Yangi kelgan"></label><label>Tavsif<textarea name="description" rows="4" required minlength="10" maxlength="2000">${escapeHTML(b.description||'')}</textarea></label>${errorBox}<button class="primary" type="submit">Saqlash ↗</button></form>`; }
function renderAdminWorkspace() {
    main.innerHTML=heading('Do‘kon boshqaruvi.', 'Lokal ma’lumotlar bazasi · Onlayn to‘lov sinov rejimida','ADMIN PANELI')+`<div class="admin-toolbar"><div class="tabs">${[['overview','Umumiy'],['books','Kitoblar'],['orders','Buyurtmalar'],['reviews','Sharhlar']].map(([id,label])=>`<button data-admin-tab="${id}" class="${adminTab===id?'selected':''}">${label}${id==='reviews'&&adminData.reviews.some(r=>r.status==='pending')?' •':''}</button>`).join('')}</div><div class="button-row"><button class="secondary" data-refresh-admin>Yangilash ↻</button><button class="secondary" data-logout>Chiqish</button></div></div><div id="admin-body" class="page-section"></div>`; renderAdminBody();
}
function renderAdminBody() {
    const {books:allBooks,orders,reviews:allReviews}=adminData;
    if(adminTab==='overview') {
        const active=orders.filter(o=>o.status!=='cancelled'), revenue=active.reduce((s,o)=>s+o.total,0);
        $('#admin-body').innerHTML=`<div class="stats-grid">${[['Katalogdagi kitoblar',allBooks.filter(b=>!b.archived).length],['Buyurtmalar',orders.length],['Buyurtmalar qiymati',money(revenue)],['Kutilayotgan sharhlar',allReviews.filter(r=>r.status==='pending').length]].map(([label,value])=>`<div class="panel stat"><span>${label}</span><strong>${value}</strong></div>`).join('')}</div><p class="inline-note">Buyurtmalar qiymati tushum degani emas: naqd to‘lovlar hali to‘lanmagan, onlayn to‘lovlar esa sinov. Bekor qilingan buyurtmalar hisobga olinmaydi.</p><div class="two-columns"><section class="panel"><h2>So‘nggi buyurtmalar</h2>${orders.length?orders.slice(-5).reverse().map(o=>`<div class="summary-line"><span>${o.id}<small class="block">${escapeHTML(o.customer.name)}</small></span><span class="badge ${o.status}">${statuses[o.status]}</span></div>`).join(''):'<p class="muted">Hali buyurtmalar yo‘q.</p>'}</section><section class="panel"><h2>Zaxira nazorati</h2>${allBooks.filter(b=>!b.archived&&b.stock<5).map(b=>`<div class="summary-line"><span>${escapeHTML(b.title)}</span><strong>${b.stock} dona</strong></div>`).join('')||'<p class="muted">Barcha kitoblarda zaxira yetarli.</p>'}</section></div>`;
    } else if(adminTab==='books') {
        $('#admin-body').innerHTML=`<div class="table-wrap panel"><table><caption>Kitoblar va zaxira</caption><thead><tr><th>Kitob</th><th>Janr</th><th>Narx</th><th>Zaxira</th><th>Amallar</th></tr></thead><tbody>${allBooks.map(b=>`<tr class="${b.archived?'archived':''}"><td><strong>${escapeHTML(b.title)}</strong><small class="block">${escapeHTML(b.author)}${b.archived?' · Arxivda':''}</small></td><td>${escapeHTML(b.category)}</td><td>${money(b.price)}</td><td>${b.stock}</td><td><div class="button-row"><button class="secondary small" data-edit-book="${b.id}">Tahrirlash</button><button class="secondary small" data-archive-book="${b.id}">${b.archived?'Tiklash':'Arxivlash'}</button></div></td></tr>`).join('')}</tbody></table></div><div id="book-form-container" class="page-section">${adminBookForm()}</div>`;
    } else if(adminTab==='orders') {
        $('#admin-body').innerHTML=orders.length?orders.slice().reverse().map(o=>`<div class="admin-order">${orderCard(o)}<div class="panel customer-panel"><h3>Mijoz</h3><p>${escapeHTML(o.customer.name)} · ${escapeHTML(o.customer.phone)}</p><p>${escapeHTML(o.customer.address||'Olib ketish — manzil va vaqt kelishiladi')}</p>${transitions[o.status]?.length?`<form class="status-form" data-order-id="${o.id}"><label>Keyingi holat<select name="status">${transitions[o.status].map(s=>`<option value="${s}">${statuses[s]}</option>`).join('')}</select></label><button class="secondary" type="submit">Holatni saqlash</button>${errorBox}</form>`:'<p class="muted">Bu buyurtma yakunlangan.</p>'}</div></div>`).join(''):empty('Hali buyurtmalar yo‘q.','#catalog','Katalogga o‘tish');
    } else {
        $('#admin-body').innerHTML=allReviews.length?allReviews.slice().reverse().map(r=>`<div class="moderation-card">${reviewCard(r)}<div class="moderation-actions"><span class="badge ${r.status}">${statuses[r.status]}</span>${r.status!=='approved'?`<button class="secondary" data-moderate="${r.id}" data-status="approved">Tasdiqlash ✓</button>`:''}${r.status!=='rejected'?`<button class="secondary danger" data-moderate="${r.id}" data-status="rejected">Rad etish</button>`:''}</div></div>`).join(''):empty('Tekshirish uchun sharhlar yo‘q.','#reviews','Sharhlarga o‘tish');
    }
}
async function reloadAdmin() { adminData=await api('/admin/data'); await refreshPublic(); renderAdminWorkspace(); }
function setActive(page) { $$('nav a').forEach(a=>{const active=a.hash==='#'+page;a.classList.toggle('active',active); if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');}); }
async function route() {
    if(!ready)return;
    const sequence=++routeSequence, [path,query='']=(location.hash.slice(1)||'home').split('?'), params=new URLSearchParams(query), page=path.split('/')[0];
    $('#cart-dialog').close(); setActive(page); window.scrollTo(0,0);
    document.title=({home:'Bosh sahifa',catalog:'Kitoblar',search:'Qidiruv',book:'Kitob haqida',adviser:'Kitob tavsiyachisi',reviews:'Sharhlar',checkout:'Buyurtma va to‘lov',orders:'Buyurtmalarim',favorites:'Sevimlilar',about:'Biz haqimizda',admin:'Admin paneli'}[page]||'Sahifa')+' · Kitobzor';
    try {
        if(page==='home')main.innerHTML=heroHTML+`<section class="page-section"><div class="section-line"><div><div class="eyebrow">KITOB JAVONI</div><h2>Siz uchun saraladik</h2></div><a class="text-link" href="#catalog">Barcha kitoblar ↗</a></div><div class="book-grid">${books.slice(0,4).map(card).join('')}</div></section><section class="adviser-banner panel"><span>✳</span><div><h2>Qaysi kitobni tanlashni bilmaysizmi?</h2><p>Qiziqish va byudjetingizni ayting. Sizga mosini topamiz.</p></div><a class="primary" href="#adviser">Tavsiyachini ochish ↗</a></section>`+aboutHTML;
        else if(page==='catalog'||page==='search'){filters={q:params.get('q')||'',category:params.get('category')||'all',budget:params.get('budget')||'',sort:params.get('sort')||'popular',available:params.get('available')==='true'};catalogShell(page==='search');}
        else if(page==='book')renderBook(Number(path.split('/')[1]));
        else if(page==='adviser')renderAdviser();else if(page==='reviews')renderReviews();else if(page==='checkout')renderCheckout();
        else if(page==='orders')await renderOrders(sequence);else if(page==='admin')await renderAdmin(sequence);else if(page==='about')renderAbout();
        else if(page==='favorites'){const list=books.filter(b=>favorites.includes(b.id));main.innerHTML=heading('Yana qaytib o‘qiydiganlar.', 'Siz saqlagan kitoblar shu brauzerda qoladi.','SEVIMLILAR')+(list.length?`<div class="book-grid page-section">${list.map(card).join('')}</div>`:empty('Hozircha sevimli kitoblar yo‘q. Kitob yonidagi yurakchani bosing.'));}
        else main.innerHTML=heading('Sahifa topilmadi.')+empty('Bu manzil mavjud emas.','#home','Bosh sahifaga qaytish');
    } catch(error) { if(sequence===routeSequence) main.innerHTML=heading('Ulanishda muammo.')+`<div class="panel empty"><p>${escapeHTML(error.message)}</p><button class="primary" data-retry>Qayta urinish ↻</button></div>`; }
}
document.addEventListener('click',async event=>{
    const target=event.target.closest('button,a');if(!target)return;
    if(target.matches('.skip-link')){event.preventDefault();main.focus();return;}
    if(target.matches('[data-scroll-reviews]')){event.preventDefault();$('#book-reviews')?.scrollIntoView({behavior:'smooth'});return;}
    if(target.matches('[data-add]'))add(Number(target.dataset.add));
    if(target.matches('[data-close-cart]'))$('#cart-dialog').close();
    if(target.matches('[data-favorite]')){const id=Number(target.dataset.favorite);favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];save('kitobzor-favorites',favorites);const isSaved=favorites.includes(id);$$(`[data-favorite="${id}"]`).forEach(b=>{b.classList.toggle('saved',isSaved);b.setAttribute('aria-pressed',String(isSaved));b.textContent=b.classList.contains('favorite')?(isSaved?'♥':'♡'):(isSaved?'♥ Saqlangan':'♡ Saqlash');});if(location.hash==='#favorites')route();}
    if(target.matches('[data-change]')){const id=target.dataset.change,b=books.find(b=>b.id===Number(id));if(!b)return;cart[id]=Math.min(b.stock,99,(cart[id]||0)+Number(target.dataset.delta));if(cart[id]<1)delete cart[id];sessionStorage.removeItem('kitobzor-pending-order');updateCart();}
    if(target.matches('[data-remove]')){delete cart[target.dataset.remove];sessionStorage.removeItem('kitobzor-pending-order');updateCart();}
    if(target.matches('[data-reset-filters]')){filters={};catalogShell(true);history.replaceState(null,'','#search');}
    if(target.matches('[data-retry],[data-refresh-orders]')){if(!ready)init();else route();}
    if(target.matches('[data-forget-order]')){orderReceipts=orderReceipts.filter(r=>r.id!==target.dataset.forgetOrder);save('kitobzor-receipts',orderReceipts);route();}
    if(target.matches('[data-admin-tab]')){adminTab=target.dataset.adminTab;renderAdminWorkspace();}
    if(target.matches('[data-edit-book]')){const b=adminData.books.find(b=>b.id===Number(target.dataset.editBook));$('#book-form-container').innerHTML=adminBookForm(b);$('#book-form').scrollIntoView({behavior:'smooth',block:'start'});}
    if(target.matches('[data-new-book]'))$('#book-form-container').innerHTML=adminBookForm();
    const adminAction=target.matches('[data-refresh-admin],[data-logout],[data-archive-book],[data-moderate]');
    if(adminAction)target.disabled=true;
    try{
        if(target.matches('[data-refresh-admin]'))await reloadAdmin();
        if(target.matches('[data-logout]')){await api('/admin/logout',{method:'POST',data:{}});adminData=null;route();}
        if(target.matches('[data-archive-book]')){await api('/admin/books/'+target.dataset.archiveBook+'/archive',{method:'PUT',data:{}});await reloadAdmin();toast('Katalog yangilandi');}
        if(target.matches('[data-moderate]')){await api('/admin/reviews/'+target.dataset.moderate,{method:'PUT',data:{status:target.dataset.status}});await reloadAdmin();toast('Sharh holati yangilandi');}
    }catch(error){toast(error.message);if(error.status===401)route();}finally{if(adminAction)target.disabled=false;}
});
document.addEventListener('input',event=>{if(event.target.matches('#search,#budget-filter'))renderResults();});
document.addEventListener('change',event=>{
    if(event.target.matches('#category-filter,#sort,#stock-filter'))renderResults();
    if(event.target.matches('#review-filter')){const list=reviews.filter(r=>event.target.value==='all'||r.bookId===Number(event.target.value));$('#review-list').innerHTML=list.length?list.slice().reverse().map(reviewCard).join(''):'<div class="empty panel">Bu kitob uchun tasdiqlangan sharh yo‘q.</div>';}
    if(event.target.matches('#delivery')){const courier=event.target.value==='courier';$('#address-label').hidden=!courier;$('[name="address"]').required=courier;$('#pickup-note').hidden=courier;$('#checkout-summary').innerHTML=checkoutSummary();}
    if(event.target.matches('#payment'))$('#payment-note').textContent=event.target.value==='demo'?'SINOV: to‘lov muvaffaqiyatli taqlid qilinadi, haqiqiy pul yechilmaydi.':'Buyurtma saqlanadi; to‘lov qabul qilish vaqtida amalga oshiriladi.';
});
document.addEventListener('submit',async event=>{
    const form=event.target;event.preventDefault();
    if(form.id==='search-form'){renderResults();return;}
    if(form.id==='adviser-form'){recommend(form);return;}
    const button=$('[type="submit"]',form); if(button?.disabled)return;if(button)button.disabled=true;const box=$('.form-error',form);if(box)box.hidden=true;
    try{
        const values=Object.fromEntries(new FormData(form));
        if(form.id==='login-form'){await api('/admin/login',{method:'POST',data:values});await route();toast('Admin paneliga kirdingiz');}
        if(form.id==='review-form'){await api('/reviews',{method:'POST',data:{...values,bookId:Number(values.bookId),rating:Number(values.rating)}});form.reset();const success=$('.form-success',form);success.hidden=false;success.textContent='Rahmat! Sharhingiz admin tasdig‘i uchun yuborildi.';}
        if(form.id==='checkout-form')await placeOrder(form);
        if(form.id==='book-form'){const id=values.id;delete values.id;values.price=Number(values.price);values.stock=Number(values.stock);await api('/admin/books'+(id?'/'+id:''),{method:id?'PUT':'POST',data:values});await reloadAdmin();toast('Kitob saqlandi');}
        if(form.matches('.status-form')){await api('/admin/orders/'+form.dataset.orderId,{method:'PUT',data:values});await reloadAdmin();toast('Buyurtma holati yangilandi');}
    }catch(error){showError(form,error);}finally{if(button)button.disabled=false;}
});
$('#open-cart').onclick=()=>{renderCart();$('#cart-dialog').showModal();};$('#close-cart').onclick=()=>$('#cart-dialog').close();$('#cart-dialog').addEventListener('click',e=>{if(e.target===$('#cart-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
window.addEventListener('hashchange',route);$('#year').textContent=new Date().getFullYear();
async function init(){main.innerHTML='<div class="empty" role="status">Kitob javoni yuklanmoqda…</div>';try{await refreshPublic();ready=true;await route();}catch(error){main.innerHTML=heading('Serverga ulanib bo‘lmadi.')+`<div class="empty panel"><p>Lokal server ishlayotganini tekshiring.</p><p>${escapeHTML(error.message)}</p><button class="primary" data-retry>Qayta urinish ↻</button></div>`;}}
init();
